/// Build an envelope from a redacted Xberg document.
#[napi(js_name = "editorEnvelopeFromDocument")]
pub fn editor_envelope_from_document(
    document: JsExtractedDocument,
    options: JsEditorProjectionOptions,
) -> napi::Result<JsEditorEnvelope> {
    Ok({
        let document_core: xberg::ExtractedDocument = (document).try_into().map_err(|error: serde_json::Error| {
            napi::Error::new(
                napi::Status::InvalidArg,
                format!("invalid JSON for hacienda::ExtractedDocument: {error}"),
            )
        })?;
        let options_core: hacienda::editor_projection::EditorProjectionOptions = options.into();
        hacienda::editor_projection::EditorEnvelope::from_document(&document_core, &options_core).into()
    })
}

