/// Compute the chain hash linking an entry to its predecessor.
///
/// The timestamp is deliberately excluded so verification is reproducible.
#[napi(js_name = "computeChainHash")]
pub fn compute_chain_hash(prev_chain_hash: String, seq: i64, fields: JsChainHashFields) -> String {
    let fields_core: hacienda::audit::ChainHashFields = fields.into();

    hacienda::audit::compute_chain_hash(&prev_chain_hash, seq as u64, fields_core)
}

/// Compute the blake3 hash that seals a segment's metadata.
///
/// Every field is length-prefixed before being fed to the hasher. This prevents
/// ambiguous splits: without length prefixes, `("ab", "c")` and `("a", "bc")` would
/// produce the same byte sequence. `compute_chain_hash` in `entry.rs` uses fixed-width
/// integers (which are self-delimiting) alongside string bytes and does not need this
/// guard, but the seal fields are all variable-length strings, so it is required here.
///
/// The field order and encoding here is the canonical definition of the seal hash for
/// this crate. Changing either breaks all stored seals.
///
/// The nine arguments map one-to-one to the nine `SegmentSeal` fields that the hash
/// covers. Wrapping them in a struct would force callers to construct one just to call this
/// function; keeping them flat is both more legible and consistent with `compute_chain_hash`.
#[allow(clippy::too_many_arguments)]
#[napi(js_name = "computeSealHash")]
pub fn compute_seal_hash(
    prev_seal_hash: Option<String>,
    segment_id: Option<String>,
    tenant_id: Option<String>,
    node_id: Option<String>,
    config_hash: Option<String>,
    sealed_tip: Option<String>,
    entry_count: Option<i64>,
    opened_at: Option<String>,
    sealed_at: Option<String>,
) -> Result<String> {
    let segment_id = segment_id
        .ok_or_else(|| napi::Error::new(napi::Status::InvalidArg, "missing required parameter 'segment_id'"))?;
    let tenant_id = tenant_id
        .ok_or_else(|| napi::Error::new(napi::Status::InvalidArg, "missing required parameter 'tenant_id'"))?;
    let node_id =
        node_id.ok_or_else(|| napi::Error::new(napi::Status::InvalidArg, "missing required parameter 'node_id'"))?;
    let config_hash = config_hash
        .ok_or_else(|| napi::Error::new(napi::Status::InvalidArg, "missing required parameter 'config_hash'"))?;
    let sealed_tip = sealed_tip
        .ok_or_else(|| napi::Error::new(napi::Status::InvalidArg, "missing required parameter 'sealed_tip'"))?;
    let entry_count = entry_count
        .ok_or_else(|| napi::Error::new(napi::Status::InvalidArg, "missing required parameter 'entry_count'"))?;
    let opened_at = opened_at
        .ok_or_else(|| napi::Error::new(napi::Status::InvalidArg, "missing required parameter 'opened_at'"))?;
    let sealed_at = sealed_at
        .ok_or_else(|| napi::Error::new(napi::Status::InvalidArg, "missing required parameter 'sealed_at'"))?;
    Ok({
        hacienda::audit::compute_seal_hash(
            prev_seal_hash.as_deref(),
            &segment_id,
            &tenant_id,
            &node_id,
            &config_hash,
            &sealed_tip,
            entry_count as u64,
            &opened_at,
            &sealed_at,
        )
    })
}

