            __result.vlm_config = val.vlm_config.map(Into::into);
            __result.vlm_prompt = val.vlm_prompt;
            __result.acceleration = val.acceleration.map(Into::into);
            __result.security_limits = val.security_limits.map(Into::into);
            __result.tessdata_bytes = val
                .tessdata_bytes
                .map(|m| m.into_iter().map(|(k, v)| (k, v.to_vec().into())).collect());
            __result.tessdata_path = val.tessdata_path.map(Into::into);
