impl From<JsOcrBoundingGeometry> for xberg::OcrBoundingGeometry {
    fn from(val: JsOcrBoundingGeometry) -> Self {
        match val.type_tag.as_str() {
            "rectangle" => Self::Rectangle {
                left: val.left.unwrap_or_default(),
                top: val.top.unwrap_or_default(),
                width: val.width.unwrap_or_default(),
                height: val.height.unwrap_or_default(),
            },
            "quadrilateral" => Self::Quadrilateral {
                points: val
                    .points
                    .map(|v| v.into_iter().map(Into::into).collect())
                    .unwrap_or_default(),
            },
            _ => Self::Rectangle {
                left: Default::default(),
                top: Default::default(),
                width: Default::default(),
                height: Default::default(),
            },
        }
    }
}

impl From<xberg::OcrBoundingGeometry> for JsOcrBoundingGeometry {
    fn from(val: xberg::OcrBoundingGeometry) -> Self {
        match val {
            xberg::OcrBoundingGeometry::Rectangle {
                left,
                top,
                width,
                height,
            } => Self {
                type_tag: "rectangle".to_string(),
                height: Some(height),
                left: Some(left),
                points: None,
                top: Some(top),
                width: Some(width),
            },
            xberg::OcrBoundingGeometry::Quadrilateral { points } => Self {
                type_tag: "quadrilateral".to_string(),
                height: None,
                left: None,
                points: Some(points.into_iter().map(Into::into).collect()),
                top: None,
                width: None,
            },
        }
    }
}

