impl TryFrom<JsOutputFormat> for xberg::OutputFormat {
    type Error = serde_json::Error;
    fn try_from(val: JsOutputFormat) -> std::result::Result<Self, serde_json::Error> {
        serde_json::from_value(val.0)
    }
}
impl JsOutputFormat {
    fn try_into_core(self) -> napi::Result<xberg::OutputFormat> {
        <xberg::OutputFormat as TryFrom<Self>>::try_from(self).map_err(|error| {
            napi::Error::new(
                napi::Status::InvalidArg,
                format!("invalid JSON for xberg::OutputFormat: {error}"),
            )
        })
    }
}

impl From<xberg::OutputFormat> for JsOutputFormat {
    fn from(val: xberg::OutputFormat) -> Self {
        Self(serde_json::to_value(val).expect("serializing xberg::OutputFormat to JSON failed"))
    }
}

