// Error variant name constants
pub const JOB_ERROR_ERROR_NOT_FOUND: &str = "NotFound";
pub const JOB_ERROR_ERROR_NOT_FOUND_CODE: u32 = 2;
pub const JOB_ERROR_ERROR_STATUS_MISMATCH: &str = "StatusMismatch";
pub const JOB_ERROR_ERROR_STATUS_MISMATCH_CODE: u32 = 2;
pub const JOB_ERROR_ERROR_RETRY_DISABLED: &str = "RetryDisabled";
pub const JOB_ERROR_ERROR_RETRY_DISABLED_CODE: u32 = 2;
pub const JOB_ERROR_ERROR_DELETE_UNSUPPORTED: &str = "DeleteUnsupported";
pub const JOB_ERROR_ERROR_DELETE_UNSUPPORTED_CODE: u32 = 2;
pub const JOB_ERROR_ERROR_INTERNAL: &str = "Internal";
pub const JOB_ERROR_ERROR_INTERNAL_CODE: u32 = 2;

/// Convert a `hacienda::jobs::JobError` error to a NAPI error.
///
/// The stable numeric error code is deliberately not interpolated into this message —
/// `napi::Error` has no per-variant subclass to attach it to. When available, it is exposed
/// as a structured `code` field on the `*Info` companion class instead (see
/// `gen_napi_error_class`), never smuggled into human-facing text.
#[allow(dead_code)]
fn job_error_to_napi_err(e: hacienda::jobs::JobError) -> napi::Error {
    let mut error = napi::Error::new(napi::Status::GenericFailure, e.to_string());
    let (kind, error_code): (&str, u32) = match &e {
        hacienda::jobs::JobError::NotFound(..) => ("NotFound", 2),
        hacienda::jobs::JobError::StatusMismatch { .. } => ("StatusMismatch", 2),
        hacienda::jobs::JobError::RetryDisabled { .. } => ("RetryDisabled", 2),
        hacienda::jobs::JobError::DeleteUnsupported(..) => ("DeleteUnsupported", 2),
        hacienda::jobs::JobError::Internal(..) => ("Internal", 2),
        #[allow(unreachable_patterns)]
        _ => ("Unknown", 2),
    };
    let info = format!(
        "{{\"kind\":{},\"errorCode\":{}}}",
        serde_json::Value::String(kind.to_string()),
        error_code
    );
    error.set_cause(napi::Error::new(
        napi::Status::GenericFailure,
        format!("alef:error-info:{info}"),
    ));
    error
}

