pub const TENANT_ERROR_ERROR_NOT_FOUND_CODE: u32 = 2;
pub const TENANT_ERROR_ERROR_INTERNAL: &str = "Internal";
pub const TENANT_ERROR_ERROR_INTERNAL_CODE: u32 = 2;

/// Convert a `hacienda::tenancy::TenantError` error to a NAPI error.
///
/// The stable numeric error code is deliberately not interpolated into this message —
/// `napi::Error` has no per-variant subclass to attach it to. When available, it is exposed
/// as a structured `code` field on the `*Info` companion class instead (see
/// `gen_napi_error_class`), never smuggled into human-facing text.
#[allow(dead_code)]
fn tenant_error_to_napi_err(e: hacienda::tenancy::TenantError) -> napi::Error {
    let mut error = napi::Error::new(napi::Status::GenericFailure, e.to_string());
    let (kind, error_code): (&str, u32) = match &e {
        hacienda::tenancy::TenantError::AlreadyExists(..) => ("AlreadyExists", 2),
        hacienda::tenancy::TenantError::NotFound(..) => ("NotFound", 2),
        hacienda::tenancy::TenantError::Internal(..) => ("Internal", 2),
        #[allow(unreachable_patterns)]
        _ => ("Unknown", 2),
    };
    let info = format!(
        "{{\"kind\":{},\"errorCode\":{}}}",
        serde_json::Value::String(kind.to_string()),
        error_code
    );
    error.set_cause(napi::Error::new(
        napi::Status::GenericFailure,
        format!("alef:error-info:{info}"),
    ));
    error
}

#[allow(dead_code)]
fn alef_napi_err<E: std::fmt::Display + 'static>(e: E) -> napi::Error {
    let message = e.to_string();
    let boxed: Box<dyn std::any::Any> = Box::new(e);
    let boxed = match boxed.downcast::<hacienda::jobs::JobError>() {
        Ok(typed) => return job_error_to_napi_err(*typed),
        Err(other) => other,
    };
    let boxed = match boxed.downcast::<hacienda::store::object::ObjectStoreError>() {
        Ok(typed) => return object_store_error_to_napi_err(*typed),
        Err(other) => other,
    };
    let boxed = match boxed.downcast::<hacienda::tenancy::TenantError>() {
        Ok(typed) => return tenant_error_to_napi_err(*typed),
        Err(other) => other,
    };
    drop(boxed);
    napi::Error::new(napi::Status::GenericFailure, message)
}
